/* ---------- visibility helper ---------- */
function onVisible(el,cb,opts){const io=new IntersectionObserver(es=>es.forEach(e=>cb(e.isIntersecting)),opts||{threshold:0});io.observe(el)}
function once(el,cb,th){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){cb();io.disconnect()}}),{threshold:th||0.25});io.observe(el)}

