function goldLogoCanvas(size,color){
  const c=document.createElement('canvas');const r=462/504;c.width=Math.round(size*r);c.height=size;
  const g=c.getContext('2d');g.drawImage(logoImg,0,0,c.width,c.height);g.globalCompositeOperation='source-in';
  if(color){g.fillStyle=color}else{const gr=g.createLinearGradient(0,0,0,c.height);gr.addColorStop(0,'#FFF1C4');gr.addColorStop(.45,'#F2CD7A');gr.addColorStop(.75,'#C8913A');gr.addColorStop(1,'#F5D78A');g.fillStyle=gr}
  g.fillRect(0,0,c.width,c.height);return c;
}

