  const pts=new T.Points(g,mat);const grp=new T.Group();grp.add(pts);scene.add(grp);
  // dust
  const DN=isMobile?350:700;const dp=new Float32Array(DN*3);for(let i=0;i<DN;i++){dp[i*3]=(Math.random()-.5)*40;dp[i*3+1]=(Math.random()-.5)*26;dp[i*3+2]=(Math.random()-.5)*20-4}
  const dg=new T.BufferGeometry();dg.setAttribute('position',new T.BufferAttribute(dp,3));
  const dust=new T.Points(dg,new T.PointsMaterial({color:0xF2CD7A,size:.07,transparent:true,opacity:.55,blending:T.AdditiveBlending,depthWrite:false}));scene.add(dust);
