  const jt=new T.Mesh(new T.BoxGeometry(5.2,1,1),[std(0x111111),std(0x111111),std(0x1a1a1a),std(0x111111),std(0xffffff,{map:jTex}),std(0x111111)]);jt.position.set(0,.5,5.6);G.add(jt);
