  const crateTex=tex(256,256,(g,w,h)=>{g.fillStyle='#6b4a2a';g.fillRect(0,0,w,h);for(let y=0;y<h;y+=64){g.fillStyle='rgba(0,0,0,.25)';g.fillRect(0,y,w,4)}g.strokeStyle='#3a2616';g.lineWidth=14;g.strokeRect(7,7,w-14,h-14);g.beginPath();g.moveTo(10,10);g.lineTo(w-10,h-10);g.stroke();g.fillStyle='rgba(0,0,0,.55)';g.font='600 34px Oswald';g.fillText('BATTLE CHINA',26,140)});
  [[4.9,.6,2.6,0],[4.9,1.6,2.6,.3]].forEach(c=>{const b=new T.Mesh(new T.BoxGeometry(1.2,1,1.2),std(0xffffff,{map:crateTex}));b.position.set(c[0],c[1]-.1,c[2]);b.rotation.y=c[3];b.scale.setScalar(c[1]>1?.85:1);G.add(b)});
