  // chain-link fence + banners
  const fenceTex=tex(512,256,(g,w,h)=>{g.clearRect(0,0,w,h);g.strokeStyle='rgba(190,190,190,.8)';g.lineWidth=2;for(let x=-h;x<w;x+=22){g.beginPath();g.moveTo(x,0);g.lineTo(x+h,h);g.stroke();g.beginPath();g.moveTo(x+h,0);g.lineTo(x,h);g.stroke()}});
  fenceTex.wrapS=T.RepeatWrapping;fenceTex.repeat.set(3,1);
  const banTex=tex(1024,160,(g,w,h)=>{g.fillStyle='#B3121D';g.fillRect(0,0,w,h);g.fillStyle='#F2CD7A';g.fillRect(0,0,w,8);g.fillRect(0,h-8,w,8);for(let i=0;i<3;i++)sticker(g,170+i*340,h/2,280,110,(i-1)*.02,'合作品牌',null)});
  [-5.5,5.5].forEach(x=>{const f=new T.Mesh(new T.PlaneGeometry(9,2.4),new T.MeshBasicMaterial({map:fenceTex,transparent:true,side:T.DoubleSide,depthWrite:false}));f.position.set(x,1.2,8.8);G.add(f);
    const b=new T.Mesh(new T.PlaneGeometry(8.6,1),new T.MeshBasicMaterial({map:banTex}));b.position.set(x,1.1,8.82);G.add(b);
    [-4.5,0,4.5].forEach(px=>{const p=new T.Mesh(new T.CylinderGeometry(.05,.05,2.5,6),std(0x888888,{metalness:.8}));p.position.set(x+px,1.25,8.8);G.add(p)})});
  // pop-up shop
  const shop=new T.Group();const sTex=tex(700,180,(g,w,h)=>{g.fillStyle='#F2CD7A';g.fillRect(0,0,w,h);g.fillStyle='#8E0E17';g.font='900 74px "Noto Serif SC",serif';g.textAlign='center';g.textBaseline='middle';g.fillText('品牌快闪店',w/2,h/2-8);g.font='600 28px Oswald';g.fillText('POP-UP STORE',w/2,h-24)});
  const sb=new T.Mesh(new T.BoxGeometry(3.6,2.4,2.4),std(0xF5EEE1,{roughness:.6}));sb.position.y=1.2;shop.add(sb);
  const win=new T.Mesh(new T.PlaneGeometry(2.8,1.3),new T.MeshBasicMaterial({color:0xFFD98A}));win.position.set(0,1.25,1.21);shop.add(win);
  const sign=new T.Mesh(new T.BoxGeometry(3.9,.8,.2),new T.MeshBasicMaterial({map:sTex}));sign.position.set(0,2.8,1.25);shop.add(sign);
  const awn=new T.Mesh(new T.BoxGeometry(3.9,.1,1),std(0xB3121D));awn.position.set(0,2.35,1.65);awn.rotation.x=.25;shop.add(awn);
  shop.position.set(-10,0,4.6);shop.rotation.y=.55;G.add(shop);
  // festoon lights
  const bulbMat=new T.MeshBasicMaterial({color:0xFFD98A});const bulbs=[];
  const poles=[[-9.5,-5.2],[9.5,-5.2],[9.5,7.6],[-9.5,7.6]];
  poles.forEach(p=>{const m=new T.Mesh(new T.CylinderGeometry(.08,.1,7.5,8),std(0x222222,{metalness:.6}));m.position.set(p[0],3.75,p[1]);G.add(m)});
  [[0,1],[1,2],[3,0],[0,2],[1,3]].forEach(pr=>{const a=poles[pr[0]],b=poles[pr[1]];const N=18;const pts=[];
    for(let i=0;i<=N;i++){const u=i/N;const x=a[0]+(b[0]-a[0])*u,z=a[1]+(b[1]-a[1])*u,y=7.3-Math.sin(u*Math.PI)*1.3;pts.push(new T.Vector3(x,y,z));
      if(i%2===1){const bl=new T.Mesh(new T.SphereGeometry(.09,8,8),bulbMat.clone());bl.position.set(x,y-.14,z);G.add(bl);bulbs.push(bl)}}
    G.add(new T.Line(new T.BufferGeometry().setFromPoints(pts),new T.LineBasicMaterial({color:0x222222})))});
  // people
  function person(opt){const g=new T.Group();const body=std(opt.col,{roughness:.8});const skin=std(0x2a1a14);
    const legs=new T.Mesh(new T.CylinderGeometry(.2,.17,.9,8),std(0x151515));legs.position.y=.45;g.add(legs);
    const torso=new T.Mesh(new T.CylinderGeometry(.26,.22,.75,8),body);torso.position.y=1.28;g.add(torso);
    const head=new T.Mesh(new T.SphereGeometry(.19,12,10),skin);head.position.y=1.86;g.add(head);
    if(opt.cap){const c=new T.Mesh(new T.CylinderGeometry(.2,.2,.08,12),std(opt.cap));c.position.y=2;g.add(c);const b=new T.Mesh(new T.BoxGeometry(.2,.03,.18),std(opt.cap));b.position.set(0,1.98,.18);g.add(b)}
    const armL=new T.Group(),armR=new T.Group();[armL,armR].forEach((a,i)=>{const m=new T.Mesh(new T.CylinderGeometry(.07,.06,.7,6),body);m.position.y=-.35;a.add(m);a.position.set(i?.32:-.32,1.6,0);g.add(a)});
    g.userData={armL,armR,up:opt.up,ph:Math.random()*6.283};return g}
  const cols=[0x1a1a1a,0x222222,0x2b2b2b,0x8E0E17,0x1d1d2a,0xD9A441,0x333333,0xF5EEE1];
