/* ---------- GLOBE ---------- */
fontsReady.then(()=>{
  const canvas=$('#globeCanvas'),box=$('#globeBox');const renderer=makeRenderer(canvas);
  const scene=new T.Scene();const cam=new T.PerspectiveCamera(32,1,.1,200);cam.position.set(0,0,40);
  const R=10;const tilt=new T.Group();tilt.rotation.x=.38;scene.add(tilt);const spin=new T.Group();tilt.add(spin);
  const ll=(lat,lon,r)=>{const p=(90-lat)*Math.PI/180,th=(lon+180)*Math.PI/180;return new T.Vector3(-r*Math.sin(p)*Math.cos(th),r*Math.cos(p),r*Math.sin(p)*Math.sin(th))};
  spin.add(new T.Mesh(new T.SphereGeometry(R*.985,48,48),new T.MeshBasicMaterial({color:0x2a0508})));
  const DN=isMobile?1400:2400;const dp=new Float32Array(DN*3);const gold=Math.PI*(3-Math.sqrt(5));
  for(let i=0;i<DN;i++){const y=1-(i/(DN-1))*2,r=Math.sqrt(1-y*y),th=gold*i;dp[i*3]=Math.cos(th)*r*R;dp[i*3+1]=y*R;dp[i*3+2]=Math.sin(th)*r*R}
  const dg=new T.BufferGeometry();dg.setAttribute('position',new T.BufferAttribute(dp,3));
  spin.add(new T.Points(dg,new T.PointsMaterial({color:0xE2B155,size:.11,transparent:true,opacity:.55})));
  const gm=new T.LineBasicMaterial({color:0xE2B155,transparent:true,opacity:.22});
  for(let lat=-60;lat<=60;lat+=30){const pts=[];for(let lo=0;lo<=360;lo+=6)pts.push(ll(lat,lo,R*1.002));spin.add(new T.Line(new T.BufferGeometry().setFromPoints(pts),gm))}
  for(let lo=0;lo<360;lo+=30){const pts=[];for(let la=-90;la<=90;la+=6)pts.push(ll(la,lo,R*1.002));spin.add(new T.Line(new T.BufferGeometry().setFromPoints(pts),gm))}
  const halo=new T.Sprite(new T.SpriteMaterial({map:tex(256,256,(g,w,h)=>{const gr=g.createRadialGradient(128,128,90,128,128,128);gr.addColorStop(0,'rgba(242,205,122,.0)');gr.addColorStop(.72,'rgba(242,205,122,.22)');gr.addColorStop(1,'rgba(242,205,122,0)');g.fillStyle=gr;g.fillRect(0,0,w,h)}),transparent:true,depthWrite:false,blending:T.AdditiveBlending}));
  halo.scale.set(R*2.9,R*2.9,1);scene.add(halo);
  function label(txt,col){const s=new T.Sprite(new T.SpriteMaterial({map:tex(256,96,(g,w,h)=>{g.font='900 46px "Noto Serif SC",serif';g.textAlign='center';g.textBaseline='middle';g.lineWidth=8;g.strokeStyle='rgba(36,4,7,.85)';g.strokeText(txt,w/2,h/2);g.fillStyle=col;g.fillText(txt,w/2,h/2)}),transparent:true,depthTest:false}));s.scale.set(4.2,1.6,1);return s}
  const GZ=[23.13,113.26];const home=ll(GZ[0],GZ[1],R);
  const hm=new T.Mesh(new T.SphereGeometry(.34,16,16),new T.MeshBasicMaterial({color:0xFFF1C4}));hm.position.copy(home);spin.add(hm);
  const hl=label('广州 · 澳门','#FFF1C4');hl.position.copy(ll(GZ[0]-4,GZ[1],R*1.08));spin.add(hl);
  const pulse=new T.Mesh(new T.RingGeometry(.4,.55,32),new T.MeshBasicMaterial({color:0xF9E1A0,transparent:true,side:T.DoubleSide}));pulse.position.copy(home.clone().multiplyScalar(1.01));pulse.lookAt(home.clone().multiplyScalar(2));spin.add(pulse);
  const DEST=[['万象',17.97,102.63,1],['巴黎',48.86,2.35,0],['洛杉矶',34.05,-118.24,0],['东京',35.68,139.69,0]];
  const arcs=[];
  DEST.forEach((d,i)=>{const b=ll(d[1],d[2],R);const dist=home.distanceTo(b);const mid=home.clone().add(b).multiplyScalar(.5).normalize().multiplyScalar(R+Math.max(1.6,dist*.42));
    const curve=new T.QuadraticBezierCurve3(home,mid,b);const geo=new T.TubeGeometry(curve,90,.07,6,false);
    const m=new T.Mesh(geo,new T.MeshBasicMaterial({color:d[3]?0xFFF1C4:0xE0404A,transparent:true,opacity:d[3]?.95:.75}));spin.add(m);
    const dm=new T.Mesh(new T.SphereGeometry(.26,12,12),new T.MeshBasicMaterial({color:0xF2CD7A}));dm.position.copy(b);spin.add(dm);
    const lb=label(d[0]+(d[3]?' · 2017':''),d[3]?'#FFF1C4':'#F2CD7A');lb.position.copy(ll(d[1]+4,d[2],R*1.1));spin.add(lb);
    const spark=new T.Sprite(new T.SpriteMaterial({map:tex(64,64,(g)=>{const gr=g.createRadialGradient(32,32,0,32,32,32);gr.addColorStop(0,'rgba(255,248,220,1)');gr.addColorStop(.35,'rgba(242,205,122,.8)');gr.addColorStop(1,'rgba(242,205,122,0)');g.fillStyle=gr;g.fillRect(0,0,64,64)}),transparent:true,depthWrite:false,blending:T.AdditiveBlending}));spark.scale.set(1.4,1.4,1);spin.add(spark);
    arcs.push({curve,geo,n:geo.index.count,spark,off:i*.33})});
  const base=Math.atan2(-home.x,home.z);spin.rotation.y=base;
  const st={target:0,cur:0,user:false};dragRotate(canvas,st,.008);
  loop(box,t=>{if(!fit(renderer,cam,canvas))return;
    const drift=reduce?0:t*.12;st.cur+=(st.target-st.cur)*.08;spin.rotation.y=base+Math.sin(drift*.6)*1.35+st.cur;
    arcs.forEach(a=>{const p=((t*.28+a.off)%1.25);const k=Math.min(1,p);a.geo.setDrawRange(0,Math.floor(a.n*k/3)*3);a.spark.visible=p<1;if(p<1)a.spark.position.copy(a.curve.getPoint(k))});
    const s=1+((t*1.2)%1)*1.6;pulse.scale.set(s,s,s);pulse.material.opacity=1-((t*1.2)%1);
    renderer.render(scene,cam)});
});

